/**
 * Sub-pixel draw frames on the web canvas host.
 *
 * `fixtures/draw-wire-subpixel.json` is generated by the Rust encoder
 * (`core-libs/petal-ui/src/draw_wire.rs`, test `subpixel_fixture_is_current`):
 * a frame of `FrameCommand`s, mostly `SubCommand`s with fractional geometry,
 * as `DrawWire::encode_frame` puts it on the wire and as serde's JSON. A
 * `SubCommand` uses its whole-pixel twin's opcode and layout, so the one
 * decoder reads both. Every fraction in the fixture is exact in f32, so the
 * comparison is exact.
 *
 * The renderer half: fractional numbers reach the Canvas2D calls as they are,
 * and only a command marked `subpixel` changes image smoothing.
 */
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import {
  decodeDrawCommands,
  decodeFrameCommands,
} from "../../integrations/petal-web-canvas/src/draw-wire.js";
import {
  renderCommands,
  type DrawCommand,
} from "../../integrations/petal-web-canvas/src/canvas-renderer.js";

const fixture = JSON.parse(
  readFileSync(join(__dirname, "fixtures/draw-wire-subpixel.json"), "utf8"),
) as { numbers: number[]; strings: string[]; commands: any[] };

describe("sub-pixel draw wire decoding", () => {
  it("decodes every command of the sub-pixel fixture exactly", () => {
    const decoded = decodeDrawCommands(new Float64Array(fixture.numbers), fixture.strings);
    expect(decoded.length).toBe(fixture.commands.length);
    decoded.forEach((cmd, i) =>
      expect(cmd, `commands[${i}] (${fixture.commands[i].op})`).toEqual(fixture.commands[i]),
    );
  });

  it("keeps the fixture's fractions", () => {
    // The fixture would be no test of fractions if it had none.
    const fractional = fixture.numbers.filter((n) => !Number.isInteger(n));
    expect(fractional.length).toBeGreaterThan(20);
    const decoded = decodeDrawCommands(fixture.numbers, fixture.strings);
    const circle = decoded.find((c) => c.op === "circle")!;
    expect([circle.cx, circle.cy, circle.radius]).toEqual([1.5, -2.25, 0.625]);
  });

  it("decodeFrameCommands marks exactly the sub-pixel commands", () => {
    const subIndices = Uint32Array.from([1, 3, 9, 999]); // 999: past the end, ignored
    const decoded = decodeFrameCommands(fixture.numbers, fixture.strings, subIndices);
    decoded.forEach((cmd, i) => {
      if ([1, 3, 9].includes(i)) {
        expect(cmd.subpixel, `commands[${i}]`).toBe(true);
        const { subpixel, ...rest } = cmd;
        expect(rest).toEqual(fixture.commands[i]);
      } else {
        expect("subpixel" in cmd, `commands[${i}]`).toBe(false);
        expect(cmd).toEqual(fixture.commands[i]);
      }
    });
  });

  it("decodeFrameCommands with no indices is decodeDrawCommands", () => {
    expect(decodeFrameCommands(fixture.numbers, fixture.strings, [])).toEqual(
      decodeDrawCommands(fixture.numbers, fixture.strings),
    );
  });
});

// ── Renderer ──────────────────────────────────────────────────────────────

interface Call {
  name: string;
  args: unknown[];
  smoothing: boolean;
}

/** A Canvas2D stub recording every method call with the image-smoothing
 * setting in force at the time. Properties are plain fields. */
function makeCtx(width = 200, height = 200) {
  const calls: Call[] = [];
  const fields: Record<string | symbol, unknown> = {
    canvas: { width, height },
    imageSmoothingEnabled: false, // a host page that turned it off
    globalAlpha: 1,
    calls,
  };
  const ctx = new Proxy(fields, {
    get(target, key) {
      if (key in target) return target[key];
      return (...args: unknown[]) => {
        calls.push({ name: String(key), args, smoothing: target.imageSmoothingEnabled as boolean });
        // What a `create*Gradient` returns; ignored by every other caller.
        return { addColorStop() {} };
      };
    },
    set(target, key, value) {
      target[key] = value;
      return true;
    },
  });
  return ctx as any;
}

const savedImage = (globalThis as any).Image;
const savedDocument = (globalThis as any).document;
afterEach(() => {
  (globalThis as any).Image = savedImage;
  (globalThis as any).document = savedDocument;
});

/** Stub `Image` so every source loads at once (the renderer's cache then
 * serves it from the second frame). */
function stubImages(): void {
  (globalThis as any).Image = class {
    complete = true;
    naturalWidth = 16;
    width = 16;
    height = 16;
    src = "";
    onload: (() => void) | null = null;
    onerror: (() => void) | null = null;
  };
}

/** Stub `document.createElement("canvas")` for offscreen canvases. */
function stubDocument(): void {
  (globalThis as any).document = {
    createElement() {
      const el: any = { width: 1, height: 1 };
      el.getContext = () => {
        const c = makeCtx(el.width, el.height);
        c.canvas = el;
        return c;
      };
      return el;
    },
  };
}

describe("canvas renderer, sub-pixel commands", () => {
  it("passes fractional geometry to the context unchanged", () => {
    const ctx = makeCtx();
    const cmds: DrawCommand[] = [
      { op: "circle", cx: 10.25, cy: 20.5, radius: 3.75, r: 1, g: 2, b: 3, subpixel: true },
      { op: "line", x1: 0.5, y1: 1.5, x2: 9.25, y2: 4.75, r: 1, g: 2, b: 3, width: 1.5, subpixel: true },
      { op: "polygon", points: [[0.5, 0.5], [10.25, 0.5], [5.125, 8.875]], r: 1, g: 2, b: 3, subpixel: true },
    ];
    renderCommands(ctx, cmds, 200, 200);
    const by = (name: string) => ctx.calls.filter((c: Call) => c.name === name).map((c: Call) => c.args);
    expect(by("arc")[0].slice(0, 3)).toEqual([10.25, 20.5, 3.75]);
    expect(by("moveTo")).toContainEqual([0.5, 1.5]);
    expect(by("lineTo")).toContainEqual([9.25, 4.75]);
    expect(by("lineTo")).toContainEqual([5.125, 8.875]);
    // No smoothing change for anything but images.
    expect(ctx.imageSmoothingEnabled).toBe(false);
  });

  it("smooths a sub-pixel image and leaves a snapped one to the context", () => {
    stubImages();
    const image = (subpixel: boolean): DrawCommand => ({
      op: "image", source: `img-${subpixel}.png`, x: 1.5, y: 2.25, w: 32, h: 32,
      ...(subpixel ? { subpixel } : {}),
    });
    const ctx = makeCtx();
    // First frame starts the loads; the second draws.
    renderCommands(ctx, [image(true), image(false)], 200, 200);
    ctx.calls.length = 0;
    renderCommands(ctx, [image(true), image(false)], 200, 200);
    const draws = ctx.calls.filter((c: Call) => c.name === "drawImage");
    expect(draws.length).toBe(2);
    expect(draws[0].smoothing).toBe(true);
    expect(draws[0].args.slice(5)).toEqual([1.5, 2.25, 32, 32]);
    expect(draws[1].smoothing).toBe(false);
    // Restored after the sub-pixel draw.
    expect(ctx.imageSmoothingEnabled).toBe(false);
  });

  it("smooths a sub-pixel draw_canvas and leaves a snapped one to the context", () => {
    stubDocument();
    const ctx = makeCtx();
    renderCommands(
      ctx,
      [
        { op: "create_canvas", id: 1, w: 8, h: 8 },
        { op: "draw_canvas", id: 1, x: 2.5, y: 3.25, subpixel: true },
        { op: "draw_canvas", id: 1, x: 2, y: 3 },
      ],
      200,
      200,
    );
    const draws = ctx.calls.filter((c: Call) => c.name === "drawImage");
    expect(draws.map((d: Call) => [d.smoothing, ...d.args.slice(1, 3)])).toEqual([
      [true, 2.5, 3.25],
      [false, 2, 3],
    ]);
    expect(ctx.imageSmoothingEnabled).toBe(false);
  });

  it("a whole-pixel frame never touches image smoothing", () => {
    stubImages();
    stubDocument();
    const decoded = decodeDrawCommands(fixture.numbers, fixture.strings);
    const ctx = makeCtx();
    const sets: unknown[] = [];
    const proxy = new Proxy(ctx, {
      set(target, key, value) {
        if (key === "imageSmoothingEnabled") sets.push(value);
        target[key] = value;
        return true;
      },
    });
    renderCommands(proxy, decoded, 200, 200);
    renderCommands(proxy, decoded, 200, 200);
    expect(sets).toEqual([]);
  });
});
